"use strict";

// Test-only: run a functional suite against HQ's interface-v1 TARGET
// registry (contract-draft/registry/, generated by
// `node scripts/pin-bridge-contract.js --target --write`) instead of the
// pinned CF Meet contract in src/bridge/contracts/.
//
// Why: Track A's real contract ships most capabilities BLOCKED_DEPENDENCY or
// DISABLED with {"not":{}} results until each phase lands, so HQ's reads,
// commands, reports and pipeline would have nothing to exercise. The target
// model uses the same ids, paths, shapes, approvals and kinds as the pinned
// contract wherever both define a capability; boundaries.test.js enforces
// that on every pin. Contract tests (boundaries, api-contracts) do NOT load
// this helper and always check the real pin.
//
// Load it before anything from src/: `require("./helpers/target-contract");`
// as the first statement of a test file. node --test runs each file in its
// own process, so the redirect never leaks into the contract tests.

const Module = require("node:module");
const path = require("node:path");

const CONTRACTS = path.resolve(__dirname, "..", "..", "src", "bridge", "contracts");
const TARGET = path.resolve(__dirname, "..", "..", "contract-draft", "registry");
const FILES = new Set(["cfmeet-capabilities.v1.json", "cfmeet-bridge-schemas.v1.json", "cfmeet-event-adapters.v1.json", "cfmeet-backoffice-v1.json"]);

if (!Module.__cfmeetTargetContract) {
  const resolve = Module._resolveFilename;
  Module._resolveFilename = function resolveTarget(request, parent, ...rest) {
    const resolved = resolve.call(this, request, parent, ...rest);
    if (FILES.has(path.basename(resolved)) && path.dirname(path.resolve(resolved)) === CONTRACTS) return path.join(TARGET, path.basename(resolved));
    return resolved;
  };
  Module.__cfmeetTargetContract = true;
}

module.exports = { TARGET, CONTRACTS, FILES };
